package com.quincaisoft.commerce.application;
import com.quincaisoft.commerce.api.*;import com.quincaisoft.subscriptions.api.EntitlementService;import com.quincaisoft.commerce.infrastructure.*;import com.quincaisoft.catalog.api.CatalogService;import com.quincaisoft.identity.api.IdentityService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.util.function.*;import java.security.*;import java.nio.charset.StandardCharsets;
@Service public class DefaultCommerceService implements CommerceService {
 private final EntitlementService entitlements;private final EntityManager em;private final ScopedTransactions tx;private final CatalogService catalog;private final IdentityService identity;private final JsonMapper json;
 public DefaultCommerceService(EntityManager em,ScopedTransactions tx,CatalogService catalog,IdentityService identity,JsonMapper json,EntitlementService entitlements){this.entitlements=entitlements;this.em=em;this.tx=tx;this.catalog=catalog;this.identity=identity;this.json=json;}
 private void owner(){var s=TenantContext.current();if(identity.members().stream().noneMatch(m->m.actorId().equals(s.actorId())&&m.active()&&m.role().equals("owner")))throw new org.springframework.security.access.AccessDeniedException("Owner required");}
 private Store current(boolean lock){var s=TenantContext.current();return em.find(Store.class,new Store.Key(s.tenantId(),s.companyId(),s.branchId()),lock?LockModeType.PESSIMISTIC_WRITE:LockModeType.NONE);}
 private StoreView view(Store s){return new StoreView(s.id,s.slug,s.displayName,s.enabled,Long.toString(s.version));}
 private ListingView view(Listing l){return new ListingView(l.id,l.productId,l.title,l.description,l.unit,Long.toString(l.priceXaf),l.published,Long.toString(l.version));}
 public StoreView store(){return tx.execute(()->{owner();var s=current(false);return s==null?new StoreView(null,"","",false,"0"):view(s);});}
 public StoreView configure(Configure c){if(c==null||c.slug()==null||!c.slug().matches("[a-z0-9][a-z0-9-]{2,62}"))throw new IllegalArgumentException("Slug must be 3–63 lowercase letters, digits or hyphens");text(c.displayName(),120);text(c.reason(),2000);return tx.execute(()->{owner();if(c.enabled())entitlements.requireCommerce();return once(c.operationId(),c,StoreView.class,()->{var scope=TenantContext.current();var s=current(true);if(s==null){if(c.version()!=0)throw new RevisionConflict("Store version changed");s=new Store();s.tenantId=scope.tenantId();s.companyId=scope.companyId();s.branchId=scope.branchId();s.id=scope.branchId();s.slug=c.slug();s.displayName=c.displayName();s.enabled=c.enabled();em.persist(s);}else{if(s.version!=c.version())throw new RevisionConflict("Store version changed");s.slug=c.slug();s.displayName=c.displayName();s.enabled=c.enabled();}em.flush();return view(s);});});}
 public List<ListingView> listings(){return tx.execute(()->{owner();var s=current(false);if(s==null)return List.of();return em.createQuery("select l from Listing l where l.tenantId=:t and l.companyId=:c and l.storeId=:s order by l.title,l.id",Listing.class).setParameter("t",s.tenantId).setParameter("c",s.companyId).setParameter("s",s.id).setMaxResults(200).getResultList().stream().map(this::view).toList();});}
 public ListingView publish(Publish c){if(c==null||c.productId()==null)throw new IllegalArgumentException("Product required");text(c.title(),200);if(c.description()==null||c.description().length()>3000)throw new IllegalArgumentException("Description exceeds limit");text(c.reason(),2000);return tx.execute(()->{owner();if(c.published())entitlements.requireCommerce();return once(c.operationId(),c,ListingView.class,()->{var s=current(true);if(s==null)throw new IllegalStateException("Configure storefront first");var p=catalog.get(c.productId());if(c.published()&&(!p.active()||p.taxBasisPoints()!=0))throw new IllegalArgumentException("Public pricing requires active zero-tax product until gross-price policy is configured");var found=em.createQuery("select l from Listing l where l.tenantId=:t and l.companyId=:c and l.storeId=:s and l.productId=:p",Listing.class).setParameter("t",s.tenantId).setParameter("c",s.companyId).setParameter("s",s.id).setParameter("p",p.id()).getResultList();Listing l;if(found.isEmpty()){if(c.version()!=0)throw new RevisionConflict("Listing version changed");l=new Listing();l.tenantId=s.tenantId;l.companyId=s.companyId;l.branchId=s.branchId;l.storeId=s.id;l.id=UUID.randomUUID();l.productId=p.id();}else{l=found.getFirst();if(l.version!=c.version())throw new RevisionConflict("Listing version changed");}l.title=c.title();l.description=c.description();l.priceXaf=p.sellingPriceXaf();l.unit=p.baseUnit();l.published=c.published();if(found.isEmpty())em.persist(l);em.flush();return view(l);});});}
 @Transactional(readOnly=true) public PublicStore publicStore(String slug){if(slug==null||!slug.matches("[a-z0-9][a-z0-9-]{2,62}"))throw new IllegalArgumentException("Invalid store");var stores=em.createNativeQuery("select p.display_name from public_store_projection p join public_publication_gate g on g.id=p.publication_gate where p.slug=:s and g.enabled and g.expires_at>now()").setParameter("s",slug).getResultList();if(stores.isEmpty())throw new NoSuchElementException("Store not found");List<?> raw=em.createNativeQuery("select id,title,description,unit,price_xaf from public_listing_projection where slug=:s order by title,id limit 200").setParameter("s",slug).getResultList();var items=raw.stream().map(row->{Object[] r=(Object[])row;return new PublicItem((UUID)r[0],(String)r[1],(String)r[2],(String)r[3],r[4].toString());}).toList();return new PublicStore(slug,(String)stores.getFirst(),items,"Confirm availability with the merchant","CHECKOUT_NOT_ENABLED");}
 private static void text(String x,int max){if(x==null||x.isBlank()||x.length()>max)throw new IllegalArgumentException("Required text exceeds permitted length");}
 private <T>T once(UUID op,Object input,Class<T> type,Supplier<T> action){if(op==null)throw new IllegalArgumentException("Operation required");var s=TenantContext.current();String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((type.getName()+json.writeValueAsString(input)).getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var found=em.createNativeQuery("select request_hash,response_json::text,company_id,branch_id from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",op).getResultList();if(!found.isEmpty()){Object[] row=(Object[])found.getFirst();if(!hash.equals(row[0])||!s.companyId().equals(row[2])||!s.branchId().equals(row[3]))throw new IllegalStateException("Operation reused");return json.readValue((String)row[1],type);}var result=action.get();UUID id=result instanceof StoreView v?v.id():((ListingView)result).id();em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json)values(:t,:o,:c,:b,:h,'COMMERCE_PUBLICATION',:id,cast(:j as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("id",id).setParameter("j",json.writeValueAsString(result)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload)values(:t,:e,:c,:b,:o,'StorefrontPublication.v1','commerce',:id,cast(:j as jsonb))").setParameter("t",s.tenantId()).setParameter("e",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).setParameter("id",id).setParameter("j",json.writeValueAsString(result)).executeUpdate();return result;}
}